#include "CloudLearningRank.h"
#include <algorithm>
#include <map>
#include <set>
namespace private_input::activity {namespace {
std::string identity(const Json&e){return e.at("reading").str()+char(31)+e.at("text").str();}
Json archive(Json rows){auto out=emptyLearning();out["entries"]=std::move(rows);return out;}
Json combine(const Json&a,const Json&b){std::map<std::string,Json>left;for(const auto&e:a.at("entries").items)left[identity(e)]=e;for(const auto&e:b.at("entries").items)if(left.count(identity(e))){const auto&old=left.at(identity(e));if(old.at("pinVersion").dump()==e.at("pinVersion").dump())require(old.at("pinned").boolean()==e.at("pinned").boolean(),"cloud rank pin equivocation");}return mergeLearning(a,b);}
bool laterPin(const Json&a,const Json&b){auto x=a.at("sequence").num(),y=b.at("sequence").num();return x>y||(x==y&&a.at("device").str()>b.at("device").str());}
}
Json cloudRankProjection(const Json&shadow,const Json&native,const std::vector<std::string>&producers){validateLearning(native);require(!producers.empty()&&producers.size()<=2,"cloud rank producer bound");const auto&model=shadow.at("model");validateCloudStagedModel(model);require(model.kind==Json::Kind::object&&model.at("terms").items.size()<=CurrentLearningCapacity.model_term_rows&&model.at("tombstones").items.size()<=CurrentLearningCapacity.model_tombstone_rows,"cloud rank requires staged model");auto local=native,baseline=emptyLearning();std::map<std::string,Json>covered;std::map<std::string,std::map<std::string,Json>>coveredRows;
 for(const auto&p:producers){auto actor=uuidText(parseId(p));const auto&owned=shadow.at("modelBaselines").at(actor);require(owned.at("digest").str()==cloudComponentDigest(actor,owned.at("records")),"cloud rank baseline digest");bool found=false;for(const auto&w:model.at("producer_watermarks").items)if(w.at("producer_id").str()==actor)found=w.at("producer_revision").num()==owned.at("revision").num()&&w.at("component_digest").str()==owned.at("digest").str();require(found,"cloud rank model producer not covered");covered[actor]=archive(owned.at("records"));for(const auto&e:owned.at("records").items)coveredRows[actor][identity(e)]=e;baseline=combine(baseline,covered.at(actor));auto latest=cloudMergeComponents(owned.at("records"),cloudOwnComponents(native,actor),actor);local=combine(local,archive(latest));}
 std::map<std::string,Json>rows,base,terms,tombstones;for(const auto&e:local.at("entries").items)rows[identity(e)]=e;for(const auto&e:baseline.at("entries").items)base[identity(e)]=e;for(const auto&e:model.at("terms").items)terms[identity(e)]=e;for(const auto&e:model.at("tombstones").items)tombstones[identity(e)]=e;
 // Model-only lexemes remain available for spelling discovery even before old
 // legacy peers deliver their v1 archive. No cloud counts are written to native.
 for(const auto&p:terms)if(!rows.count(p.first))rows[p.first]=Json::object({{"reading",p.second.at("reading")},{"text",p.second.at("text")},{"generation",p.second.at("term_generation")},{"deleted",false},{"counts",Json::object()},{"pinned",false},{"pinVersion",Json::object({{"sequence",0},{"device",""}})}});
 Json output=Json::array(),fallback=Json::array(),scores=Json::object();for(const auto&p:rows){auto row=p.second;if(!cloudLearningTermEligible(row)){if(!row.at("deleted").boolean())fallback.items.push_back(row);continue;}uint64_t generation=row.at("generation").num();if(terms.count(p.first))generation=std::max(generation,terms.at(p.first).at("term_generation").num());if(tombstones.count(p.first))generation=std::max(generation,tombstones.at(p.first).at("term_generation").num());bool deleted=row.at("generation").num()==generation&&row.at("deleted").boolean();if(tombstones.count(p.first)&&tombstones.at(p.first).at("term_generation").num()==generation)deleted=true;if(deleted)continue;uint64_t weight=terms.count(p.first)&&terms.at(p.first).at("term_generation").num()==generation?terms.at(p.first).at("weight").num():0;require(weight<=200000,"cloud rank model weight bound");uint64_t delta=0;
 for(const auto&actor:covered){uint64_t previous=0;auto found=coveredRows.at(actor.first).find(p.first);if(found!=coveredRows.at(actor.first).end()){const auto&e=found->second;if(e.at("generation").num()==generation&&!e.at("deleted").boolean())previous=e.at("counts").at(actor.first).num();}uint64_t current=row.at("generation").num()==generation&&row.at("counts").has(actor.first)?row.at("counts").at(actor.first).num():0;delta=std::min(uint64_t(200),delta+(current>previous?current-previous:0));}
 weight=std::min(uint64_t(200000),weight+delta*1000);bool pin=row.at("pinned").boolean();if(terms.count(p.first)&&terms.at(p.first).at("term_generation").num()==generation){bool localControl=base.count(p.first)?laterPin(row.at("pinVersion"),base.at(p.first).at("pinVersion")):row.at("pinVersion").at("sequence").num()>0;if(!localControl)pin=terms.at(p.first).at("pinned").boolean();}
 auto score=weight*5000; // [0,200000] -> existing [0,1e9] recent IPC scalar.
 scores[p.first]=score;output.items.push_back(Json::object({{"reading",row.at("reading")},{"text",row.at("text")},{"pinned",pin},{"frequency",0}}));}
 // The current mapping also carries all local fallback terms and explicit
 // personal rows. Refuse an oversized union so the owner falls back to its
 // complete local view instead of clipping the tail of either source.
 require(output.items.size()+fallback.items.size()<=CurrentLearningCapacity.term_rows,"cloud rank display union bounds");return Json::object({{"rows",output},{"localFallback",fallback},{"scores",scores},{"modelVersion",model.at("version")}});
}
}
